import { spawnSync } from 'node:child_process';
import { pbkdf2Sync } from 'node:crypto';
import { writeFileSync } from 'node:fs';

const EXE = '/workspace/dataset/test6_executable';

const R = (s, n) => s.repeat(n);
const pairs = [];
const add = (passphrase, salt, tag) => pairs.push({ passphrase, salt, tag });

// --- 1. the four sample cases from the Python file's comments (8 pairs) ---
add('bhCqzZV^', '$2b$12$f521Zvhc8Ddk7KB0UzFbyR', 'sample1-ab');
add('wTBxJJ5t', 'salt_687014', 'sample1-cd');
add('+")$o,oI', '$2b$12$t3cCqw30fC3hXZpnZVLSw3', 'sample2-ab');
add('v;rAAh+S', '$2b$12$9WYA6dr3PiS3ipjTu1pW1R', 'sample2-cd');
add('5bHAF_iS', 'qYgUadyC', 'sample3-ab');
add('jRvWu~j)', '$2b$12$dgvnmASJU7UIqQstpgdzKJ', 'sample3-cd');
add('Sd9nL1ko', '626RaGQ9KixMXOoT', 'sample4-ab');
add(')uQ*27DZ', '$2b$12$aTnnrWTZYeKgZ3IlxumDhq', 'sample4-cd');

// --- 2. canonical RFC/classic vectors ---
add('password', 'salt', 'classic-password-salt');
add('passwd', 'salt', 'passwd-salt');
add('Password', 'NaCl', 'Password-NaCl');
add('pass\0word', 'sa\0lt', 'embedded-NUL-in-both');

// --- 3. empty / minimal ---
add('', '', 'empty-both');
add('', 'salt', 'empty-passphrase');
add('password', '', 'empty-salt');
add('a', 'b', 'single-char-both');
add(' ', ' ', 'single-space-both');
add('  leading and trailing  ', '  s  ', 'surrounding-spaces');

// --- 4. HMAC key-length boundaries (UTF-8 byte length of passphrase) ---
add(R('k', 63), 'salt63', 'key-63-bytes');
add(R('k', 64), 'salt64', 'key-64-bytes');
add(R('k', 65), 'salt65', 'key-65-bytes');
add(R('k', 55), 'salt55', 'key-55-bytes');
add(R('k', 56), 'salt56', 'key-56-bytes');
add(R('k', 119), 'salt119', 'key-119-bytes');
add(R('k', 128), 'salt128', 'key-128-bytes');
add(R('k', 129), 'salt129', 'key-129-bytes');
// 63/64/65 UTF-8 bytes built from multi-byte chars: 'é' = 2 bytes, '€' = 3, emoji = 4
add(R('é', 31) + 'x', 'mb63', 'key-63-bytes-multibyte'); // 31*2+1 = 63
add(R('é', 32), 'mb64', 'key-64-bytes-multibyte');       // 32*2   = 64
add(R('é', 32) + 'x', 'mb65', 'key-65-bytes-multibyte'); // 32*2+1 = 65
add(R('€', 21), 'mb63b', 'key-63-bytes-3byte-chars');    // 21*3   = 63
add(R('\u{1F600}', 16), 'mb64b', 'key-64-bytes-emoji');  // 16*4   = 64

// --- 5. SHA-1 message-length boundaries around the 55/56/63/64 padding edges (salt side) ---
// message to HMAC inner hash is 64 (ipad) + salt + 4 bytes
add('p', R('s', 51), 'inner-block-edge-51');
add('p', R('s', 52), 'inner-block-edge-52');
add('p', R('s', 55), 'inner-block-edge-55');
add('p', R('s', 56), 'inner-block-edge-56');
add('p', R('s', 59), 'inner-block-edge-59');
add('p', R('s', 60), 'inner-block-edge-60');
add('p', R('s', 63), 'inner-block-edge-63');
add('p', R('s', 64), 'inner-block-edge-64');
add('p', R('s', 65), 'inner-block-edge-65');
add('p', R('s', 119), 'inner-block-edge-119');
add('p', R('s', 120), 'inner-block-edge-120');

// --- 6. non-ASCII / unicode ---
add('pässwörd', 'sälz', 'latin1-accents');
add('密码', '盐', 'cjk');
add('パスワード', '塩', 'japanese');
add('пароль', 'соль', 'cyrillic');
add('סיסמה', 'מלח', 'hebrew-rtl');
add('كلمة السر', 'ملح', 'arabic-rtl');
add('🔐🧂', '🧂🔐', 'emoji-only');
add('👨‍👩‍👧‍👦 family', 'ZWJ salt', 'emoji-zwj-sequence');
add('écomposed', 'nfd', 'unicode-NFD-decomposed');
add('écomposed', 'nfd', 'unicode-NFC-precomposed');
add('😀 surrogate pair', 'astral', 'astral-plane');
add('\u{10FFFF}', 'maxcodepoint', 'max-unicode-codepoint');
add('mixed é 中 \u{1F4A9} end', 'mixed é 中 \u{1F4A9}', 'mixed-widths');

// --- 7. shell-hostile / control characters ---
add('a"b\'c`d$e\\f', 'g;h|i&j<k>l', 'shell-metachars');
add('$(whoami)', '`id`', 'command-substitution-looking');
add('${HOME}', '$PATH', 'variable-expansion-looking');
add('line1\nline2', 'tab\there', 'newline-and-tab');
add('cr\rreturn', 'vt\v\f', 'cr-vt-ff');
add('*?[]{}~!#%^&*()', '+=,.:/\\', 'punctuation-soup');
add('--notanoption', '-x', 'dash-containing-values');
add('', '� ', 'control-chars');

// --- 8. long inputs (multi-hundred bytes) ---
add(R('A', 200), R('B', 200), 'long-200-200');
add(R('Long passphrase segment. ', 20), R('Long salt segment. ', 20), 'long-500ish');
add(R('x', 1000), R('y', 1000), 'long-1000-1000');
add(R('é', 300), R('中', 300), 'long-multibyte-600-900');
add(R('\u{1F680}', 128), 'rocket512', 'long-emoji-512-bytes');
add('short', R('s', 777), 'long-salt-only');
add(R('p', 777), 'short', 'long-passphrase-only');

// --- 9. bcrypt-looking salts ---
add('bcryptpass', '$2b$12$abcdefghijklmnopqrstuv', 'bcrypt-salt-2b');
add('bcryptpass', '$2a$10$N9qo8uLOickgx2ZMRZoMye', 'bcrypt-salt-2a');
add('bcryptpass', '$2y$14$1234567890123456789012', 'bcrypt-salt-2y');
add('$2b$12$notasaltbutapassphrase00', '$2b$12$f521Zvhc8Ddk7KB0UzFbyR', 'bcrypt-both');

// --- 10. digits / hex-looking / json-looking ---
add('0000000000', '1111111111', 'digits');
add('deadbeef', 'cafebabe', 'hexish');
add('{"k":"v"}', '[1,2,3]', 'json-looking');
add('a=b&c=d', '%20%41', 'urlencoded-looking');
add('0', '0', 'zero-strings');

// --- 11. repeated / identical passphrase & salt ---
add('same', 'same', 'identical');
add('salt', 'password', 'swapped-classic');

// ------------------------------------------------------------------
const results = [];
let mismatchSelf = 0, mismatchRef = 0;
for (const { passphrase, salt, tag } of pairs) {
  const r = spawnSync(EXE, ['--a', passphrase, '--b', salt, '--c', passphrase, '--d', salt], {
    encoding: 'utf8',
    maxBuffer: 1 << 24,
  });
  const out = r.stdout;
  const lines = out.split('\n');
  const ok = r.status === 0 && lines.length === 3 && lines[2] === '';
  const line1 = lines[0], line2 = lines[1];
  if (!ok) {
    console.log(`FAIL[${tag}] status=${r.status} stdout=${JSON.stringify(out)} stderr=${JSON.stringify(r.stderr)}`);
    continue;
  }
  if (line1 !== line2) { mismatchSelf++; console.log(`SELF-MISMATCH[${tag}] ${line1} vs ${line2}`); }
  const ref = pbkdf2Sync(Buffer.from(passphrase, 'utf8'), Buffer.from(salt, 'utf8'), 1000, 16, 'sha1').toString('hex');
  if (ref !== line1) { mismatchRef++; console.log(`REF-MISMATCH[${tag}] exe=${line1} ref=${ref}`); }
  results.push({ passphrase, salt, expected: line1, tag });
}

console.log(`pairs=${pairs.length} results=${results.length} selfMismatch=${mismatchSelf} refMismatch=${mismatchRef}`);
writeFileSync('/tmp/kat_raw.json', JSON.stringify(results, null, 1));

