import { readFileSync, writeFileSync } from 'node:fs';

const p = '/tmp/gen_kat.mjs';
let s = readFileSync(p, 'utf8');
const before = s;

// 1) make the NFD member of the pair genuinely decomposed: 'e' + U+0301
const nfdAnchor = ", 'nfd', 'unicode-NFD-decomposed');";
const i = s.indexOf(nfdAnchor);
if (i < 0) throw new Error('nfd anchor not found');
const lineStart = s.lastIndexOf('\n', i) + 1;
s = s.slice(0, lineStart) + "add('e\\u0301composed', 'nfd', 'unicode-NFD-decomposed');" + s.slice(i + nfdAnchor.length);

// 2) real control characters (NUL is impossible in argv, so use 0x01,0x02,0x0b,0x0c,0x1b,0x1f,0x7f)
const ctlIdx = s.indexOf("'control-chars');");
if (ctlIdx < 0) throw new Error('ctl anchor not found');
const ctlStart = s.lastIndexOf('\n', ctlIdx) + 1;
s = s.slice(0, ctlStart) +
    "add('\\x01\\x02\\x1f\\x7f ctl', '\\x0b\\x0c\\x1b ctl', 'control-chars');" +
    s.slice(ctlIdx + "'control-chars');".length);

writeFileSync(p, s);
console.log('changed:', s !== before);
for (const ln of s.split('\n')) {
  if (ln.includes('nfd') || ln.includes('control-chars')) console.log(JSON.stringify(ln));
}

import { readFileSync, writeFileSync } from 'node:fs';

const raw = JSON.parse(readFileSync('/tmp/kat_raw.json', 'utf8'));

// Fully ASCII-escape every string so the corpus file is pure 7-bit ASCII and
// therefore cannot be mangled by any charset assumption. Still standard JSON.
function jstr(s) {
  let out = '"';
  for (const ch of [...s]) {
    const cp = ch.codePointAt(0);
    if (ch === '"') out += '\\"';
    else if (ch === '\\') out += '\\\\';
    else if (cp === 0x08) out += '\\b';
    else if (cp === 0x09) out += '\\t';
    else if (cp === 0x0a) out += '\\n';
    else if (cp === 0x0c) out += '\\f';
    else if (cp === 0x0d) out += '\\r';
    else if (cp >= 0x20 && cp <= 0x7e) out += ch;
    else {
      // \uXXXX, using surrogate pairs for astral code points
      for (let i = 0; i < ch.length; i++) {
        out += '\\u' + ch.charCodeAt(i).toString(16).padStart(4, '0');
      }
    }
  }
  return out + '"';
}

const body = raw
  .map(r => `  {"passphrase": ${jstr(r.passphrase)}, "salt": ${jstr(r.salt)}, "expected": ${jstr(r.expected)}}`)
  .join(',\n');
writeFileSync('/tmp/kat_corpus.json', '[\n' + body + '\n]\n', 'latin1');

const tagged = raw
  .map(r => `  {"tag": ${jstr(r.tag)}, "passphrase": ${jstr(r.passphrase)}, "salt": ${jstr(r.salt)}, "expected": ${jstr(r.expected)}}`)
  .join(',\n');
writeFileSync('/tmp/kat_corpus_tagged.json', '[\n' + tagged + '\n]\n', 'latin1');

// ---- verification ----
const text = readFileSync('/tmp/kat_corpus.json', 'utf8');
const bytes = readFileSync('/tmp/kat_corpus.json');
let nonAscii = 0;
for (const b of bytes) if (b > 0x7e || (b < 0x20 && b !== 0x0a)) nonAscii++;
const parsed = JSON.parse(text);

let bad = 0;
if (!Array.isArray(parsed)) { bad++; console.log('NOT AN ARRAY'); }
parsed.forEach((o, i) => {
  const keys = Object.keys(o).sort().join(',');
  if (keys !== 'expected,passphrase,salt') { bad++; console.log(`bad keys @${i}: ${keys}`); }
  if (typeof o.passphrase !== 'string' || typeof o.salt !== 'string') { bad++; console.log(`bad types @${i}`); }
  if (!/^[0-9a-f]{32}$/.test(o.expected)) { bad++; console.log(`bad expected @${i}: ${JSON.stringify(o.expected)}`); }
  // round-trip: parsed strings must equal the originals exactly (code-unit wise)
  if (o.passphrase !== raw[i].passphrase || o.salt !== raw[i].salt || o.expected !== raw[i].expected) {
    bad++; console.log(`round-trip mismatch @${i} tag=${raw[i].tag}`);
  }
});

// distinctness sanity: no duplicate (passphrase,salt) keys, and expected values vary
const keyset = new Set(parsed.map(o => JSON.stringify([o.passphrase, o.salt])));
